import{_ as t,o as d,c as o,ag as r}from"./chunks/framework.BJFNwp4n.js";const i="/images/open-source/kind/kind-architecture-zh.svg",u=JSON.parse('{"title":"Kind 项目介绍","description":"Kind（Kubernetes in Docker）的项目定位、总体架构、集群创建流程、网络与镜像机制、能力边界及与同类工具的选型对比。","frontmatter":{"description":"Kind（Kubernetes in Docker）的项目定位、总体架构、集群创建流程、网络与镜像机制、能力边界及与同类工具的选型对比。","date":"2026-11-16T00:00:00.000Z","recommend":2,"tag":["Kind"],"tags":["Kubernetes","Docker","Kind"],"categories":["Open Source"]},"headers":[],"relativePath":"zh/open-source/kind/introduction.md","filePath":"zh/open-source/kind/introduction.md"}'),a={name:"zh/open-source/kind/introduction.md"};function n(c,e,l,s,k,h){return d(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794787200000"},[...e[0]||(e[0]=[r('<h1 id="kind-项目介绍" tabindex="-1">Kind 项目介绍 <a class="header-anchor" href="#kind-项目介绍" aria-label="Permalink to &quot;Kind 项目介绍&quot;">​</a></h1><p>Kind（Kubernetes in Docker）是一个在单台主机上运行 Kubernetes 集群的工具。它将每个 Kubernetes 节点封装为一个 Docker 容器，容器内运行 <code>systemd</code>、<code>containerd</code>、<code>kubelet</code> 与 <code>kubeadm</code>；多个这样的容器组成一个完整集群，其行为与上游 Kubernetes 保持一致。</p><p>Kind 由 Kubernetes SIG Testing 维护，最初用于测试 Kubernetes 自身，后来成为本地开发、CI 和多节点行为验证的常用工具。它是 CNCF 认证的一致性 Kubernetes 安装器，但并非 CNCF 托管项目。前者说明 Kind 创建的集群能够通过上游一致性测试，后者涉及项目治理，两者不应混淆。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><p>Kind 解决的核心问题是本地 Kubernetes 环境的一致性与可重复性。围绕这一目标，它形成了四项设计特征：</p><ul><li><strong>集群由容器组成</strong>：不依赖虚拟机、云主机或外部节点，所有节点都是本机 Docker 容器。</li><li><strong>版本由镜像固定</strong>：Kubernetes 版本由 <code>kindest/node</code> 镜像决定，避免宿主机工具链差异带来的漂移。</li><li><strong>拓扑由配置声明</strong>：节点数量、角色、端口映射和 kubeadm 参数都写在集群配置中，可随代码一起版本化。</li><li><strong>生命周期可反复重建</strong>：创建与删除都是显式命令，适合在 CI 中为每次任务准备独立集群。</li></ul><p>这些特征决定了 Kind 的适用边界：它面向测试与开发，而非生产环境。</p><h2 id="总体架构" tabindex="-1">总体架构 <a class="header-anchor" href="#总体架构" aria-label="Permalink to &quot;总体架构&quot;">​</a></h2><p>Kind 的架构可以按四层理解：宿主机的 Docker 引擎、Docker 网络、节点容器，以及节点容器内部的 Kubernetes 组件与业务 Pod。</p><p><img src="'+i+`" alt="Kind 总体架构"></p><table tabindex="0"><thead><tr><th>对象</th><th>说明</th></tr></thead><tbody><tr><td><code>kind</code> CLI</td><td>管理入口。单个 Go 二进制，通过 Docker API 创建、启动、检查和删除节点容器。</td></tr><tr><td>Cluster</td><td>集群实例。一组带有相同 kind 标签的节点容器，由 <code>--name</code> 区分。</td></tr><tr><td>Node container</td><td>节点载体。运行 <code>systemd</code> 与 Kubernetes 组件的 Docker 容器，分为 control-plane 与 worker。</td></tr><tr><td>Node image</td><td>版本载体。<code>kindest/node:vX.Y.Z</code>，预装指定版本的 Kubernetes 组件。</td></tr><tr><td>Cluster config</td><td>拓扑声明。<code>kind.x-k8s.io/v1alpha4</code> YAML，描述节点、网络、端口映射与 kubeadm 补丁。</td></tr><tr><td>Docker network</td><td>节点网络。Kind 创建的桥接网络，为节点容器分配 IP 并承载节点间通信。</td></tr><tr><td>kubeconfig</td><td>访问配置。宿主机上的集群访问凭证，context 名为 <code>kind-&lt;集群名&gt;</code>。</td></tr></tbody></table><p>需要区分两个“节点”概念：Kubernetes Node 是集群中的逻辑对象，Kind node container 是承载该对象的 Docker 容器。<code>kubectl get nodes</code> 查看的是前者，<code>docker ps</code> 查看的是后者。</p><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><h3 id="集群创建流程" tabindex="-1">集群创建流程 <a class="header-anchor" href="#集群创建流程" aria-label="Permalink to &quot;集群创建流程&quot;">​</a></h3><p>执行 <code>kind create cluster</code> 时，Kind 按以下顺序完成集群初始化：</p><ol><li>读取集群配置，确定节点数量、角色、镜像、网络参数和端口映射。</li><li>调用 Docker API 创建节点容器，并将节点接入 Kind 管理的 Docker 网络。</li><li>等待节点容器进入可引导状态，完成目录挂载、kubeconfig 写入和镜像预加载。</li><li>第一个 control-plane 节点执行 <code>kubeadm init</code>，其余 control-plane 节点执行 <code>kubeadm join --control-plane</code>，worker 节点执行普通 <code>kubeadm join</code>。</li><li>安装默认 CNI 与默认 StorageClass，并将 kubeconfig 合并到宿主机。</li><li>集群就绪后，通过 <code>kubectl --context kind-&lt;集群名&gt;</code> 访问 API Server；删除时，Kind 按标签清理全部节点容器与网络。</li></ol><p>从职责划分看，Docker 提供节点载体，kubeadm 完成集群引导，kubeconfig 将集群访问权交还给宿主机的 kubectl。</p><h3 id="节点容器内部" tabindex="-1">节点容器内部 <a class="header-anchor" href="#节点容器内部" aria-label="Permalink to &quot;节点容器内部&quot;">​</a></h3><p><code>kindest/node</code> 不是普通应用镜像，而是一套包含 <code>systemd</code> 引导能力、容器运行时和 Kubernetes 组件的节点根文件系统。容器启动分为四个阶段：</p><ol><li><strong>准备</strong>：入口进程暂缓启动，等待 Kind 完成目录挂载、配置写入与镜像预加载。</li><li><strong>引导 init</strong>：收到启动信号后，<code>systemd</code> 拉起 <code>containerd</code> 与 <code>kubelet</code>。</li><li><strong>组建集群</strong>：control-plane 执行 <code>kubeadm init</code> 或 <code>kubeadm join --control-plane</code>，worker 执行 <code>kubeadm join</code>。</li><li><strong>安装插件</strong>：应用默认 CNI 与 StorageClass，并导出 kubeconfig。</li></ol><p>因此，Kind 集群同时存在两套观察视角：Docker 视角看到的是 <code>kind-control-plane</code>、<code>kind-worker</code> 等容器；Kubernetes 视角看到的是容器内部注册到 API Server 的 Node。</p><h2 id="网络模型" tabindex="-1">网络模型 <a class="header-anchor" href="#网络模型" aria-label="Permalink to &quot;网络模型&quot;">​</a></h2><p>Kind 的网络分为三层：</p><ul><li><strong>节点网络</strong>：Kind 创建名为 <code>kind</code> 的 Docker 桥接网络，每个节点容器获得独立 IP，节点间通过该网络通信。</li><li><strong>Pod 网络</strong>：集群使用独立的 Pod CIDR，默认 <code>10.244.0.0/16</code>，由 <code>kindnetd</code> 负责连通。</li><li><strong>Service 网络</strong>：默认 <code>10.96.0.0/12</code>，由 <code>kube-proxy</code> 维护转发规则。Kind 默认使用 iptables 模式，Kubernetes v1.31 起可配置 nftables。</li></ul><p>从宿主机访问集群有三条路径：</p><table tabindex="0"><thead><tr><th>访问路径</th><th>适用场景</th><th>实现方式</th></tr></thead><tbody><tr><td>API Server</td><td>kubectl、CI、远程调试</td><td>Kind 将 API Server 端口映射到宿主机，kubeconfig 直接可用</td></tr><tr><td>端口映射</td><td>NodePort、Ingress、固定端口服务</td><td>在集群配置中声明 <code>extraPortMappings</code>，将宿主机端口映射到节点容器端口</td></tr><tr><td>临时转发</td><td>本地开发、一次性验证</td><td>使用 <code>kubectl port-forward</code>，不修改集群配置</td></tr></tbody></table><p>在 macOS 与 Windows 上，Docker 运行于虚拟机内部，节点容器 IP 无法从宿主机直接路由。访问工作负载必须使用端口映射或 <code>port-forward</code>。Linux 环境下节点 IP 可能可达，但为保持跨平台一致性，仍建议采用端口映射。</p><h2 id="镜像与存储" tabindex="-1">镜像与存储 <a class="header-anchor" href="#镜像与存储" aria-label="Permalink to &quot;镜像与存储&quot;">​</a></h2><h3 id="镜像分发" tabindex="-1">镜像分发 <a class="header-anchor" href="#镜像分发" aria-label="Permalink to &quot;镜像分发&quot;">​</a></h3><p>Kind 节点运行独立的 <code>containerd</code>，与宿主机的 Docker 镜像库相互隔离。<code>docker build</code> 生成的镜像不会自动出现在节点中，需要通过 <code>kind load docker-image</code> 显式导入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kind-demo:v1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kind</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-image</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kind-demo:v1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kind-multi</span></span></code></pre></div><p><code>kind load docker-image</code> 默认将镜像导入所有节点，使 Pod 无论调度到哪个节点都能使用本地镜像。若只导入部分节点，则必须通过节点亲和性或固定调度保证 Pod 落在已有镜像的节点上。</p><p>镜像标签应保持固定。Kubernetes 对 <code>:latest</code> 默认采用 <code>Always</code> 拉取策略，会绕过本地镜像访问镜像仓库。工作负载清单中应同时声明 <code>imagePullPolicy: IfNotPresent</code>，使节点优先使用本地副本。</p><h3 id="持久化存储" tabindex="-1">持久化存储 <a class="header-anchor" href="#持久化存储" aria-label="Permalink to &quot;持久化存储&quot;">​</a></h3><p>Kind 默认安装 <code>local-path-provisioner</code>，并创建名为 <code>standard</code> 的默认 StorageClass。PersistentVolume 默认落在节点容器内部的本地路径；通过 <code>extraMounts</code> 把该路径挂载到宿主机目录后，数据会写入宿主机，节点容器停止再启动或重新创建时文件仍然存在。默认存储不提供跨节点共享能力。</p><p>这一实现带来两个限制：</p><ul><li>PersistentVolume 与节点绑定。使用 PVC 的 Pod 被重新调度到其他节点后，未必能访问原有数据。</li><li>删除集群会删除节点容器及其本地数据；如果存储路径已通过 <code>extraMounts</code> 挂载到宿主机目录，宿主机上的文件会保留，但新集群不会自动识别旧 PVC。</li></ul><p>无状态工作负载应优先使用 <code>emptyDir</code> 或不声明卷。验证 StatefulSet 时，应接受数据仅存在于单节点本地，或通过亲和性将 Pod 固定在相同节点。</p><h2 id="多节点与高可用" tabindex="-1">多节点与高可用 <a class="header-anchor" href="#多节点与高可用" aria-label="Permalink to &quot;多节点与高可用&quot;">​</a></h2><p>Kind 支持多节点与多 control-plane 拓扑：</p><ul><li><strong>单 control-plane + 多 worker</strong>：常见的开发与 CI 形态，用于验证调度、亲和性、滚动更新和跨节点网络。</li><li><strong>三个 control-plane + 多 worker</strong>：模拟高可用集群。三个 control-plane 各自运行 etcd 成员并形成多数派；Kind 额外启动负载均衡容器，将 API Server 请求分发到存活的 control-plane。</li></ul><p>Kind 默认移除 control-plane 的 <code>NoSchedule</code> 污点，因此单节点集群可以直接运行工作负载。多节点环境中，如果要求业务仅运行在 worker 上，需要手动恢复该污点。</p><h2 id="生命周期" tabindex="-1">生命周期 <a class="header-anchor" href="#生命周期" aria-label="Permalink to &quot;生命周期&quot;">​</a></h2><p>Kind 将集群状态保存在 Docker 容器及其标签中，不在宿主机维护独立的集群目录。常用生命周期命令如下：</p><ul><li><code>kind create cluster --name &lt;集群名&gt;</code>：创建集群，可通过 <code>--image</code> 固定节点镜像。</li><li><code>kind get clusters</code>：列出本机全部集群。</li><li><code>kind get nodes --name &lt;集群名&gt;</code>：列出指定集群的节点容器。</li><li><code>kind export kubeconfig --name &lt;集群名&gt;</code>：重新导出 kubeconfig。</li><li><code>kind delete cluster --name &lt;集群名&gt;</code>：删除节点容器、Docker 网络及对应 kubeconfig 条目。</li></ul><p>kubeconfig 默认合并到 <code>~/.kube/config</code>，context 名为 <code>kind-&lt;集群名&gt;</code>。存在多个集群时，应通过 <code>--context</code> 明确指定目标集群。</p><h2 id="能力边界" tabindex="-1">能力边界 <a class="header-anchor" href="#能力边界" aria-label="Permalink to &quot;能力边界&quot;">​</a></h2><p>Kind 的定位是本地测试与开发环境。以下限制来自其实现方式，而非配置差异：</p><ul><li><strong>并非多机集群</strong>：所有节点共享一台宿主机、一个内核和一套 Docker 资源，无法模拟真实的跨机故障域。</li><li><strong>缺少云厂商能力</strong>：默认没有 LoadBalancer 实现，<code>type: LoadBalancer</code> 的 Service 不会获得外部 IP，需要额外组件，或改用 NodePort 与 Ingress。</li><li><strong>存储不具备共享性</strong>：默认 StorageClass 为节点本地盘，Pod 迁移后数据不会随之迁移。</li><li><strong>资源受 Docker 约束</strong>：Docker Desktop 的 CPU 与内存上限即集群上限。多节点集群与镜像构建建议至少 8 GB 内存。</li><li><strong>不构成安全边界</strong>：节点容器共享宿主机内核，不应运行不可信工作负载。</li><li><strong>镜像架构必须匹配</strong>：Apple Silicon 默认构建 arm64 镜像，节点镜像也必须为 arm64；跨架构构建需显式指定 <code>--platform</code>。</li></ul><p>常见误区及对应处理：</p><table tabindex="0"><thead><tr><th>误区</th><th>实际行为</th><th>处理方式</th></tr></thead><tbody><tr><td>构建镜像后直接部署</td><td>节点内不存在该镜像，Pod 报 <code>ErrImagePull</code></td><td>先执行 <code>kind load docker-image</code></td></tr><tr><td>使用 <code>:latest</code> 标签</td><td>默认 <code>Always</code> 拉取，本地镜像被忽略</td><td>使用固定标签并设置 <code>IfNotPresent</code></td></tr><tr><td>在 macOS 上直接访问节点 IP</td><td>节点位于 Docker 虚拟机内，宿主机不可路由</td><td>使用 <code>extraPortMappings</code> 或 <code>port-forward</code></td></tr><tr><td>将 Kind 用作生产集群</td><td>单主机、无故障域、无云集成</td><td>仅用于开发、测试与 CI</td></tr><tr><td>删除集群后仍期望保留数据</td><td>节点容器与本地卷一并删除；未挂载宿主机目录时数据随容器消失</td><td>用 <code>extraMounts</code> 挂载宿主机目录，或使用外部存储</td></tr></tbody></table><h2 id="与同类工具的选型" tabindex="-1">与同类工具的选型 <a class="header-anchor" href="#与同类工具的选型" aria-label="Permalink to &quot;与同类工具的选型&quot;">​</a></h2><p>本地 Kubernetes 工具的差异主要体现在节点形态、是否运行上游 Kubernetes，以及内置组件的完整程度：</p><table tabindex="0"><thead><tr><th>工具</th><th>节点形态</th><th>适用场景</th><th>主要限制</th></tr></thead><tbody><tr><td>Kind</td><td>每节点一个 Docker 容器，支持多节点</td><td>测试上游 Kubernetes、CI、多节点行为验证</td><td>不内置 Ingress、LoadBalancer 与 Dashboard</td></tr><tr><td>Minikube</td><td>以单节点为主，部分驱动支持多节点</td><td>学习、日常开发、使用官方 addons</td><td>启动开销较大，多节点能力依驱动而异</td></tr><tr><td>k3d</td><td>每节点一个容器，运行 k3s</td><td>轻量多节点、边缘或资源受限环境</td><td>运行 k3s 发行版，与上游 Kubernetes 存在差异</td></tr><tr><td>Docker Desktop Kubernetes</td><td>单个内置节点</td><td>已使用 Docker Desktop 的开发者快速试用</td><td>单节点、配置项有限，不适合多节点验证</td></tr></tbody></table><p>选型可依据目标判断：</p><ul><li>需要验证上游 Kubernetes 行为、进行多节点调度实验或构建 CI 环境时，选择 Kind。</li><li>需要开箱即用的学习环境，并依赖 Dashboard、Ingress 等 addon 时，选择 Minikube。</li><li>需要更轻量的多节点集群，且能够接受 k3s 与上游差异时，选择 k3d。</li><li>仅需在 Docker Desktop 中零配置试用时，选择内置 Kubernetes。</li></ul><p>Kind 的核心价值在于节点形态与上游 Kubernetes 一致，且集群可以按声明重复创建，因此适合验证节点变更、污点调整和调度策略等行为。</p><h2 id="版本与参考" tabindex="-1">版本与参考 <a class="header-anchor" href="#版本与参考" aria-label="Permalink to &quot;版本与参考&quot;">​</a></h2><p>Kind <code>v0.33.0</code> 的默认节点镜像为 <code>kindest/node:v1.37.0</code>，同时支持 v1.36.4、v1.35.8 与 v1.34.11。Kind 版本与受支持节点镜像以<a href="https://github.com/kubernetes-sigs/kind/releases" target="_blank" rel="noreferrer">官方 release notes</a>为准；集群配置字段可参考<a href="https://kind.sigs.k8s.io/docs/user/configuration/" target="_blank" rel="noreferrer">官方配置文档</a>。</p>`,59)])])}const b=t(a,[["render",n]]);export{u as __pageData,b as default};
